  if (p.type === 'bool') return (v === true || v === 'true' || v === 1 || v === '1' || v === 'on') ? 1 : 0;
  if (p.type === 'enum') { if (typeof v === 'string' && isNaN(+v)) { const i = (p.options || []).findIndex(o => o.toLowerCase() === v.toLowerCase()); return Math.max(0, i); } return Math.max(0, Math.min((p.options || []).length - 1, Math.round(+v))); }
