    const r = HS.update(ctx) || {};
    for (const k in r) { if (k === 'signals') continue; if (k === 'uniforms' && r[k] && typeof r[k] === 'object' && !Array.isArray(r[k]) && !(r[k] instanceof WebGLTexture) && !ArrayBuffer.isView(r[k])) Object.assign(S.hsU, r[k]); else S.hsU[k] = r[k]; }
