const driveOf = (p) => (p.id in S.driveMap) ? S.driveMap[p.id] : p.drive;

// ---- hosting: one effect module drawn inside another (HARNESS-NOTES "Hosting a look").
// hostEffect(id, {prefix, toBuffer = true, outName, mainName, module}) loads effects/<id>.js and returns a handle
//   { id, prefix, out: 'uBuf_<outName>', passes, params, P, on, needs, set(k, v), uniforms(), init(), frame() }
// whose `passes` are the look's passes made safe to sit in another module's pass list:
//   pass names            <name>          -> <prefix>_<name>   (its uBuf_<name> reads follow)
//   params                u_<id>          -> u_<prefix>_<id>   (declared in the pass itself; values come from handle.uniforms())
//   its own `uniform` declarations (what its frame() returns) -> <name>_<prefix>, so two hosted looks cannot collide
//   the screen pass       -> a full-res buffer named <outName> (default <prefix>_out); uPrev = that buffer's previous frame
